set-variable.value:
@{
            var m = System.Text.RegularExpressions.Regex.Replace((string)context.Variables.GetValueOrDefault("requestModel", (string)context.Variables.GetValueOrDefault("deploymentName", "")), "[^A-Za-z0-9._@\\-]", "_");
            if (m.Length == 0) { return "-"; }
            return m.Length > 64 ? m.Substring(0, 64) : m;
        }
